BEGIN;
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, document = EXCLUDED.document, revision = public.nutrition_foods.revision + 1, updated_at = now() WHERE public.nutrition_foods.user_id IS NULL;
COMMIT;
